changeSet.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM "${schema}"."user"
        WHERE email IS NULL OR TRIM(email) = ''
    ) THEN
        RAISE EXCEPTION 'Cannot derive username because tenant user email is blank in schema ${schema}';
    END IF;
END $$;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM (
            SELECT tenant_id, LOWER(TRIM(email)) AS normalized_username
            FROM "${schema}"."user"
            GROUP BY tenant_id, LOWER(TRIM(email))
            HAVING COUNT(*) > 1
        ) duplicate_usernames
    ) THEN
        RAISE EXCEPTION 'Cannot derive unique username because normalized tenant user emails collide in schema ${schema}';
    END IF;
END $$;
